@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAction: FfiConverterRustBuffer {
    typealias SwiftType = Action

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Action {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .toUi(action: try FfiConverterTypeActionUi.read(from: &buf)
        )
        
        case 2: return .toSource(action: try FfiConverterTypeActionSource.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Action, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .toUi(action):
            writeInt(&buf, Int32(1))
            FfiConverterTypeActionUi.write(action, into: &buf)
            
        
        case let .toSource(action):
            writeInt(&buf, Int32(2))
            FfiConverterTypeActionSource.write(action, into: &buf)
            
        }
    }
}


